# Minimal stand-in for perl, used only when the host has none. It
# implements just the two build-time generators PuTTY runs under perl:
# charset/sbcsgen.pl and licence.pl.
import os, re, sys


def sbcsgen(script, args):
    out = "sbcsdat.c"
    if args[:1] in (["-o"], ["--output"]):
        out = args[1]
    infile = os.path.join(os.path.dirname(script), "sbcs.dat")
    o = []
    p = o.append
    p("/*\n * sbcsdat.c - data definitions for single-byte character sets.\n"
      " *\n * Generated by sbcsgen.pl from sbcs.dat.\n"
      " * You should edit those files rather than editing this one.\n */\n\n"
      "#ifndef ENUM_CHARSETS\n\n#include \"charset.h\"\n"
      "#include \"internal.h\"\n\n")
    names = []
    name = None
    vals = []
    prio = [0] * 256

    def outcharset(name, vals, prio):
        p("static const sbcs_data data_%s = {\n    {\n" % name)
        prefix = "    "
        srt = []
        for i in range(256):
            if vals[i] < 0:
                p("%sERROR " % prefix)
            else:
                p("%s0x%04x" % (prefix, vals[i]))
                srt.append((vals[i], -prio[i], i))
            prefix = ",\n    " if i % 8 == 7 else ", "
        p("\n    },\n    {\n")
        srt.sort()
        prefix = "    "
        uval = -1
        j = 0
        for v, _, idx in srt:
            if uval == v:
                continue
            uval = v
            p("%s0x%02x" % (prefix, idx))
            prefix = ",\n    " if j % 8 == 7 else ", "
            j += 1
        p("\n    },\n    %d\n};\n" % j)
        p("const charset_spec charset_%s = {\n    %s, read_sbcs, write_sbcs, "
          "&data_%s\n};\n\n" % (name, name, name))

    for lineno, line in enumerate(open(infile, newline=""), 1):
        line = line.rstrip("\n").replace("\r", "")
        m = re.match(r"charset (.*)$", line)
        if m:
            name, vals, prio = m.group(1), [], [0] * 256
            continue
        m = re.match(r"sortpriority ([^-]*)-([^-]*) (.*)$", line)
        if m:
            for i in range(int(m.group(1), 16), int(m.group(2), 16) + 1):
                prio[i] += int(m.group(3))
            continue
        if re.match(r"[0-9a-fA-FX]", line):
            vals += [-1 if t == "XXXX" else int(t, 16)
                     for t in re.split(" +", line) if t != ""]
            if len(vals) > 256:
                sys.exit("%s:%d: charset %s has more than 256 values"
                         % (infile, lineno, name))
            if len(vals) == 256:
                outcharset(name, vals, prio)
                names.append(name)
                name, vals, prio = None, [], [0] * 256
    p("#else /* ENUM_CHARSETS */\n\n")
    for n in names:
        p("ENUM_CHARSET(%s)\n" % n)
    p("\n#endif /* ENUM_CHARSETS */\n")
    with open(out, "w") as f:
        f.write("".join(o))


def licence(script, args):
    mode = out = None
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("--header", "--licencedoc", "--copyrightdoc"):
            mode = a[2:]
        elif a in ("-o", "--output", "-output"):
            i += 1
            out = args[i]
        i += 1
    if mode is None:
        sys.exit("usage: licence.pl (--header|--licencedoc|--copyrightdoc)"
                 " [-o OUTFILE]")
    infile = os.path.join(os.path.dirname(script), "LICENCE")
    lines = [l.rstrip("\n").replace("\r", "") for l in open(infile)]
    paras = []
    cur = False
    for l in lines:
        if l == "":
            cur = False
        elif not cur:
            paras.append(l)
            cur = True
        else:
            paras[-1] += " " + l
    m = re.search(r"copyright ([^.]*)\.", paras[0], re.I)
    if not m:
        sys.exit("bad format of first paragraph")
    short = m.group(1)
    sl = lambda s: s.replace("\\", "\\\\").replace('"', '\\"')
    hb = lambda s: re.sub(r'"([^"]*)"', r"\\q{\1}",
                          re.sub(r"[\\{}]", lambda x: "\\" + x.group(0), s))
    base = os.path.basename(script)
    res = ""
    if mode == "header":
        res += ("/*\n * licence.h - macro definitions for the PuTTY licence.\n"
                " *\n * Generated by %s from %s.\n"
                " * You should edit those files rather than editing this one."
                "\n */\n\n" % (base, infile))
        res += "#define LICENCE_TEXT(parsep) \\\n"
        for i, para in enumerate(paras):
            if i > 0:
                res += "    parsep \\\n"
            res += '    "%s"' % sl(para)
            if i < len(paras) - 1:
                res += " \\"
            res += "\n"
        res += "\n"
        res += '#define SHORT_COPYRIGHT_DETAILS "%s"\n' % sl(short)
    else:
        res += ("\\# Generated by %s from %s.\n\\# You should edit those files"
                " rather than editing this one.\n\n" % (base, infile))
        if mode == "licencedoc":
            res += "\\A{licence} PuTTY \\ii{Licence}\n\n"
            for i, para in enumerate(paras):
                t = hb(para)
                if i == 0:
                    t = t.replace("copyright", "\\i{copyright}", 1)
                res += t + "\n\n"
        else:
            res += "\\define{shortcopyrightdetails} %s\n\n" % hb(short)
    if out:
        with open(out, "w") as f:
            f.write(res)
    else:
        sys.stdout.write(res)


def main():
    if len(sys.argv) < 2:
        sys.exit("fallback perl: no script given")
    if sys.argv[1] == "-v":
        print("This is perl 5, version 30 (fallback shim)")
        return
    script = os.path.abspath(sys.argv[1])
    base = os.path.basename(script)
    if base == "sbcsgen.pl":
        sbcsgen(script, sys.argv[2:])
    elif base == "licence.pl":
        licence(script, sys.argv[2:])
    else:
        sys.exit("fallback perl cannot run " + base)


if __name__ == "__main__":
    main()
